"use client";

import { Square } from "@chakra-ui/react"

export const SystemWithAnimation = () => {
  return (
    <Square size="40px" bg="tomato" animation="spin 2s infinite">
      3
    </Square>
  )
}

"use client";

import { chakra } from "@chakra-ui/react"

export const SystemWithAsChild = () => {
  return (
    <chakra.button bg="red" padding="20px" asChild>
      <a href="dfd">sdfsd</a>
    </chakra.button>
  )
}

"use client";

import { Stack, chakra } from "@chakra-ui/react"

const Badge = chakra("div", {
  base: {
    px: "4",
    py: "2",
  },
  variants: {
    variant: {
      solid: {},
      subtle: {},
    },
    pressed: {
      true: {},
      false: {},
    },
  },
  compoundVariants: [
    {
      variant: "solid",
      pressed: true,
      css: { bg: "gray.700", color: "white" },
    },
    { variant: "subtle", pressed: true, css: { bg: "gray.300" } },
  ],
  defaultVariants: {
    variant: "subtle",
  },
})

export const WithCompoundBoolean = () => {
  return (
    <Stack>
      <Badge variant="solid" colorPalette="gray">
        Hello
      </Badge>
      <Badge variant="solid" colorPalette="gray" pressed>
        Hello
      </Badge>
    </Stack>
  )
}

"use client";

import { chakra } from "@chakra-ui/react"

const Badge = chakra("div", {
  base: {
    px: "4",
    py: "2",
  },
  variants: {
    variant: {
      solid: {},
      subtle: {},
      outline: {},
    },
  },
  compoundVariants: [
    { variant: "solid", colorPalette: "gray", css: { bg: "gray.700" } },
    { variant: "subtle", colorPalette: "gray", css: { bg: "gray.300" } },
    {
      variant: "outline",
      colorPalette: "gray",
      css: { borderColor: "gray.700", color: "gray.700" },
    },
  ],
  defaultVariants: {
    variant: "subtle",
  },
})

export const WithCompoundColorPalette = () => {
  return (
    <Badge variant="solid" colorPalette="gray">
      Hello
    </Badge>
  )
}

"use client";

import { Box, useRecipe } from "@chakra-ui/react"

export const SystemWithUseRecipe = () => {
  const button = useRecipe({ key: "button" })
  return <Box css={button({ size: "md" })}>Styled like a button</Box>
}

"use client";

import { Box, useSlotRecipe } from "@chakra-ui/react"

export const SystemWithUseSlotRecipe = () => {
  const alert = useSlotRecipe({ key: "alert" })

  const styles = alert({ variant: "solid" })

  return (
    <Box css={styles.root}>
      <Box css={styles.title}>Alert Title</Box>
      <Box css={styles.description}>Alert Description</Box>
    </Box>
  )
}

